cd /tmp/elmui-probe && cat > probe.js <<'JS'
const { JSDOM } = require('jsdom');
const fs = require('fs');
const code = fs.readFileSync('elm.js', 'utf8');
const dom = new JSDOM('<!DOCTYPE html><html><head></head><body><div id="app"></div></body></html>', { runScripts: 'dangerously', pretendToBeVisual: true });
const w = dom.window;
w.eval(code);
w.Elm.Main.init({ node: w.document.getElementById('app') });
setTimeout(() => {
  console.log('=== #app innerHTML ===');
  console.log(w.document.getElementById('app').innerHTML);
  console.log('=== <head> style tags ===');
  [...w.document.querySelectorAll('style')].forEach((s, i) => {
    console.log(`--- style #${i} (${s.textContent.length} chars) ---`);
    console.log(s.textContent.slice(0, 800));
  });
}, 200);
