  const target = mod.default ?? mod
  let css
  if (typeof target?.render === 'function') css = target.render()
  else if (typeof target === 'function') css = target()
  else css = JSON.stringify(target, null, 2)
  console.log(css)
} catch (e) {
  console.error('ERROR:', e.message)
  process.exit(1)
}

