import esbuild from 'esbuild'
import { createRequire } from 'module'

const require = createRequire(import.meta.url)
const NM = '/tmp/cssr-extract/node_modules'
const keep = id => id === 'css-render' || id.startsWith('@css-render/')

async function bundle(entry) {
  const externals = new Set()
  const res = await esbuild.build({
    entryPoints: [entry],
    bundle: true,
    format: 'cjs',
    platform: 'node',
    write: false,
    nodePaths: [NM],
    logLevel: 'warning',
    plugins: [
      {
        name: 'externalize',
        setup(build) {
          build.onResolve({ filter: /.*/ }, args => {
            if (args.kind === 'entry-point') return
            const p = args.path
            if (p.startsWith('.') || p.startsWith('/')) return
            if (keep(p)) return
            externals.add(p)
            return { path: p, external: true }
          })
        }
      }
    ]
  })
  return { code: res.outputFiles[0].text, externals }
}

function stubFor(id) {
  const f = function () {
    return undefined
  }
  return new Proxy(f, {
    get: (t, p) => {
      if (p === '__esModule') return true
      if (p === 'default') return stubFor(id)
      if (p === Symbol.toPrimitive) return () => ''
      if (p === 'then') return undefined
      return stubFor(id)
    },
    apply: () => undefined,
    construct: () => ({})
  })
}

const entry = process.argv[2]
if (!entry) {
  console.error('usage: node extract.mjs <cssr.ts>')
  process.exit(1)
}

const { code, externals } = await bundle(entry)
const Module = require('module')
const m = new Module(entry)
m.filename = entry
m.paths = Module._nodeModulePaths(NM)
const origRequire = m.require.bind(m)
m.require = id => (externals.has(id) ? stubFor(id) : origRequire(id))
m._compile(code, entry)

