// Shared loader: bundles a naive-ui module (TypeScript) with esbuild, stubbing out
// runtime-only deps (vue, evtd, ...) but keeping css-render + seemly real so the
// cssr style trees and theme derivations actually execute.
import esbuild from 'esbuild'
import { createRequire } from 'module'
import { fileURLToPath } from 'url'
import path from 'path'

const require = createRequire(import.meta.url)
const here = path.dirname(fileURLToPath(import.meta.url))
export const NM = path.join(here, 'node_modules')

const KEEP = new Set(['css-render', 'seemly'])
const keep = id => KEEP.has(id) || id.startsWith('@css-render/')

const stubCache = new Map()
function stubFor(id) {
  if (stubCache.has(id)) return stubCache.get(id)
  const f = function () {
    return undefined
  }
  const p = new Proxy(f, {
    get: (t, prop) => {
      if (prop === '__esModule') return true
      if (prop === 'default') return stubFor(id)
      if (prop === Symbol.toPrimitive) return () => ''
      if (prop === 'then') return undefined
      return stubFor(id)
    },
    apply: () => undefined,
    construct: () => ({})
  })
  stubCache.set(id, p)
  return p
}

export async function loadModule(entry, source, extraSource) {
  const externals = new Set()
  const contents = extraSource ? `${source}\n${extraSource}` : source
  const res = await esbuild.build({
    stdin: {
      contents,
      resolveDir: path.dirname(entry),
      sourcefile: entry,
      loader: 'ts'
    },
    bundle: true,
    format: 'cjs',
    platform: 'node',
    write: false,
    nodePaths: [NM],
    logLevel: 'warning',
    plugins: [
      {
        name: 'externalize',
        setup(build) {
          build.onResolve({ filter: /.*/ }, args => {
            if (args.kind === 'entry-point') return
            const p = args.path
            if (p.startsWith('.') || p.startsWith('/')) return
            if (keep(p)) return
            externals.add(p)
            return { path: p, external: true }
          })
        }
      }
    ]
  })
  const code = res.outputFiles[0].text
  const Module = require('module')
  const m = new Module(entry)
  m.filename = entry
  m.paths = Module._nodeModulePaths(NM)
  const origRequire = m.require.bind(m)
  m.require = id => (externals.has(id) ? stubFor(id) : origRequire(id))
  m._compile(code, entry)
  return m.exports
}

// Render each component's cssr style tree to real CSS and write:
//   - css/naive-ui.css              (human-readable, static)
//   - src/NUI/Css/Generated.elm     (embedded string chunks, self-contained package)
import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'
import { components } from './manifest.mjs'
import { loadModule } from './_loader.mjs'

const here = path.dirname(fileURLToPath(import.meta.url))
const root = path.resolve(here, '..')
const SRC = process.env.NAIVE_UI_SRC || '/home/titan/Works/elm/naive-ui'

const banner = name => `\n/* ===== naiv ui: ${name} ===== */\n`

async function renderCssr(rel) {
  const abs = path.join(SRC, rel)
  if (!fs.existsSync(abs)) return `/* missing: ${rel} */`
  const src = `import cssr from ${JSON.stringify(abs)}\nexport default cssr`
  const mod = await loadModule(abs, src)
  const node = mod.default
  if (node && typeof node.render === 'function') return node.render()
  if (typeof node === 'function') return node()
  return `/* no render: ${rel} */`
}

const parts = []
const elmChunks = []
for (const [name, cfg] of Object.entries(components)) {
  const chunks = []
  for (const rel of cfg.cssr) {
    chunks.push(await renderCssr(rel))
  }
  const css = chunks.filter(Boolean).join('\n')
  if (!css.trim()) continue
  parts.push(banner(name) + css)
  elmChunks.push([name, css])
}

const all = parts.join('\n')

fs.mkdirSync(path.join(root, 'css'), { recursive: true })
fs.writeFileSync(path.join(root, 'css', 'naive-ui.css'), all)

const esc = s =>
  s.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\r/g, '').replace(/\n/g, '\\n')

const lines = []
lines.push('module NUI.Css.Generated exposing (..)')
lines.push('')
lines.push('{-| GENERATED FILE - do not edit by hand.')
lines.push('')
lines.push('    Regenerate with: cd tools && npm run extract')
lines.push('-}')
lines.push('')
for (const [name, css] of elmChunks) {
  lines.push(`${name} : String`)
  lines.push(`${name} =`)
  lines.push(`    "${esc(css)}"`)
  lines.push('')
}
lines.push('all : String')
lines.push('all =')
lines.push(`    String.concat [ ${elmChunks.map(([n]) => n).join(', ')} ]`)
lines.push('')

fs.mkdirSync(path.join(root, 'src', 'NUI', 'Css'), { recursive: true })
fs.writeFileSync(path.join(root, 'src', 'NUI', 'Css', 'Generated.elm'), lines.join('\n'))

console.log(`css/naive-ui.css           ${all.length} bytes`)
console.log(`src/NUI/Css/Generated.elm  ${elmChunks.length} components`)

